{
  "fields": [
    {
      "id": "space_count",
      "value": 8,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!C7:C14 (units 101–108)"
      ],
      "calculation": "Count of listed suites 101–108 = 8"
    },
    {
      "id": "occupied_count",
      "value": 7,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!F7:F14 (status flags)"
      ],
      "calculation": "Occupied statuses in F7–F13 = 7; F14 is Vacant"
    },
    {
      "id": "total_area_sf",
      "value": 23000,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!E7:E14 (areas per suite)"
      ],
      "calculation": "Sum(1800+2200+2500+3200+4000+5000+1500+2800) = 23,000 sf"
    },
    {
      "id": "occupied_area_sf",
      "value": 20200,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!E7:E14; F7:F14"
      ],
      "calculation": "Total area 23,000 sf minus vacant 108 (2,800 sf) = 20,200 sf"
    },
    {
      "id": "occupancy_count_pct",
      "value": 87.5,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!C7:C14; F7:F14"
      ],
      "calculation": "7 occupied / 8 total = 0.875 = 87.5%"
    },
    {
      "id": "occupancy_area_pct",
      "value": 87.826087,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!E7:E14; F7:F14"
      ],
      "calculation": "20,200 sf occupied / 23,000 sf total = 0.87826087 = 87.826087%"
    },
    {
      "id": "rent_roll_monthly_base",
      "value": 48600,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!G7:G13 (monthly base rent for occupied) and G14 blank"
      ],
      "calculation": "Sum(7,000+5,500+6,000+7,200+9,000+10,500+3,400) = 48,600"
    },
    {
      "id": "effective_monthly_base",
      "value": 49100,
      "evidence": [
        "Rent-Roll.xlsx | Rent Roll!G7:G13 (shows 7,000 for 101; manager note C19)",
        "Lease-File.pdf | p.2 (Executed first amendment: base rent $7,500/month effective 2026-08-01)"
      ],
      "calculation": "Adjust unit 101 from 7,000 to 7,500 per executed amendment; 48,600 + 500 = 49,100"
    },
    {
      "id": "t12_egi",
      "value": 723600,
      "evidence": [
        "T12-Statement.pdf | p.2 Annual column: GP base rent 645,600; Vacancy -46,800; Concessions -14,400; Bad debt -3,600; Other income 142,800"
      ],
      "calculation": "645,600 - 46,800 - 14,400 - 3,600 + 142,800 = 723,600"
    },
    {
      "id": "t12_operating_expenses",
      "value": 216000,
      "evidence": [
        "T12-Statement.pdf | p.2 Annual column: RE taxes 86,400; Insurance 25,200; Utilities 19,200; R&M 28,800; Payroll 18,000; Admin/legal 14,400; Mgmt fee 24,000"
      ],
      "calculation": "86,400 + 25,200 + 19,200 + 28,800 + 18,000 + 14,400 + 24,000 = 216,000"
    },
    {
      "id": "t12_noi_before_reserves",
      "value": 507600,
      "evidence": [
        "T12-Statement.pdf | p.2 Annual column (inputs as cited above)"
      ],
      "calculation": "T12 EGI 723,600 - T12 operating expenses 216,000 = 507,600"
    },
    {
      "id": "t12_reserves",
      "value": 9200,
      "evidence": [
        "T12-Statement.pdf | p.2 Annual column: Replacement reserves 9,200"
      ],
      "calculation": "Per reported annual replacement reserves"
    },
    {
      "id": "t12_ncf",
      "value": 498400,
      "evidence": [
        "T12-Statement.pdf | p.2 Annual column"
      ],
      "calculation": "T12 NOI before reserves 507,600 - T12 reserves 9,200 = 498,400"
    },
    {
      "id": "uw_egi",
      "value": 768144,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Underwriting plan: GPR $657,600; Combined revenue loss 6%; Other income $150,000)"
      ],
      "calculation": "GPR 657,600 - 6% loss (39,456) = 618,144; + Other income 150,000 = 768,144"
    },
    {
      "id": "uw_management_fee",
      "value": 30725.76,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Mgmt fee: greater of T12 actual and 4% of UW EGI)",
        "T12-Statement.pdf | p.2 Annual column: Management fee 24,000"
      ],
      "calculation": "Max(24,000; 4% x 768,144) = Max(24,000; 30,725.76) = 30,725.76"
    },
    {
      "id": "uw_operating_expenses",
      "value": 223925.76,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Underwriting adjustments by category and mgmt rule)"
      ],
      "calculation": "RE taxes 90,000 + Insurance 27,600 + Utilities 19,200 + R&M (28,800 - 4,800) 24,000 + Payroll 18,000 + Admin/legal 14,400 + Mgmt fee 30,725.76 = 223,925.76"
    },
    {
      "id": "uw_noi_before_reserves",
      "value": 544218.24,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Underwriting plan components)"
      ],
      "calculation": "UW EGI 768,144 - UW operating expenses 223,925.76 = 544,218.24"
    },
    {
      "id": "uw_reserves",
      "value": 4600,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Replacement reserves $0.20 per rentable SF per year)",
        "Rent-Roll.xlsx | Rent Roll!E7:E14 (total RSF 23,000)"
      ],
      "calculation": "0.20 x 23,000 sf = 4,600"
    },
    {
      "id": "uw_ncf",
      "value": 539618.24,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Reserve instruction)"
      ],
      "calculation": "UW NOI before reserves 544,218.24 - UW reserves 4,600 = 539,618.24"
    },
    {
      "id": "capitalization_value",
      "value": 8372588.31,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Value = UW NOI BEFORE reserves / 6.50% cap)"
      ],
      "calculation": "544,218.24 / 0.065 = 8,372,588.31"
    },
    {
      "id": "contract_rate",
      "value": 0.0625,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Contract rate 6.25% fixed)"
      ],
      "calculation": "Stated"
    },
    {
      "id": "sizing_rate",
      "value": 0.065,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Sizing rate is greater of contractual and 6.50% floor)"
      ],
      "calculation": "Max(6.25%, 6.50%) = 6.50%"
    },
    {
      "id": "annual_debt_constant",
      "value": 0.08099818,
      "evidence": [
        "Lender-Terms.pdf | p.1 (25-year amortization, monthly; annual DS = 12 monthly payments)"
      ],
      "calculation": "Monthly i = 0.065/12 = 0.0054166667; n=300; Monthly pmt factor = i / (1 - (1+i)^-n) ≈ 0.006749848; Annual constant = 12 x 0.006749848 = 0.08099818"
    },
    {
      "id": "ltv_limit",
      "value": 5442182.4,
      "evidence": [
        "Lender-Terms.pdf | p.1 (LTV 65% of indicative value)",
        "Value as computed above"
      ],
      "calculation": "0.65 x 8,372,588.31 = 5,442,182.40"
    },
    {
      "id": "dscr_limit",
      "value": 5329659,
      "evidence": [
        "Lender-Terms.pdf | p.1 (DSCR ≥ 1.25x using NCF/annual amortizing DS at sizing rate)"
      ],
      "calculation": "Allowable annual DS = UW NCF 539,618.24 / 1.25 = 431,694.592; Max loan = 431,694.592 / 0.08099818 ≈ 5,329,659"
    },
    {
      "id": "debt_yield_limit",
      "value": 6046869.33,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Debt yield min 9.00%; numerator = UW NOI before reserves)"
      ],
      "calculation": "Max loan = 544,218.24 / 0.09 = 6,046,869.33"
    },
    {
      "id": "maximum_loan",
      "value": 5329659,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Loan ceiling = lowest of LTV, DSCR, debt yield)"
      ],
      "calculation": "Min(5,442,182.40; 5,329,659; 6,046,869.33) = 5,329,659 (DSCR binds)"
    },
    {
      "id": "binding_constraint",
      "value": "DSCR",
      "evidence": [
        "Comparative limits calculated above"
      ],
      "calculation": "DSCR limit (≈$5.33MM) < LTV and Debt Yield limits"
    },
    {
      "id": "sizing_annual_debt_service",
      "value": 431694.592,
      "evidence": [
        "Lender-Terms.pdf | p.1 (DSCR definition)"
      ],
      "calculation": "At DSCR-binding maximum, Annual DS = UW NCF / 1.25 = 539,618.24 / 1.25 = 431,694.592"
    },
    {
      "id": "sizing_dscr",
      "value": 1.25,
      "evidence": [
        "Lender-Terms.pdf | p.1"
      ],
      "calculation": "UW NCF 539,618.24 / 431,694.592 = 1.25x (by construction)"
    },
    {
      "id": "sizing_debt_yield",
      "value": 0.10211,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Debt yield numerator = UW NOI before reserves)"
      ],
      "calculation": "544,218.24 / 5,329,659 ≈ 0.10211 (10.211%)"
    },
    {
      "id": "first_year_debt_service",
      "value": 422167.71,
      "evidence": [
        "Lender-Terms.pdf | p.1 (Contract rate 6.25%; 25-yr amort; 0 months IO)"
      ],
      "calculation": "Annual constant at 6.25%, 25-yr ≈ 0.0792108; DS = 5,329,659 x 0.0792108 ≈ 422,167.71"
    },
    {
      "id": "cash_to_borrower",
      "value": 1828362.41,
      "evidence": [
        "Property-and-Plan.pdf | p.1 (Existing payoff $3,400,000; Fixed closing costs $48,000)",
        "Lender-Terms.pdf | p.1 (Origination fee 1.00%)"
      ],
      "calculation": "Net = Loan 5,329,659 - Payoff 3,400,000 - Orig fee 53,296.59 - Closing 48,000 = 1,828,362.41"
    },
    {
      "id": "stress_uw_noi",
      "value": 507347.328,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Sensitivity instruction: reduce EGI 5%, recompute management; hold other OpEx constant)"
      ],
      "calculation": "Stressed EGI = 768,144 x 0.95 = 729,736.8; Mgmt = max(24,000; 4% x 729,736.8 = 29,189.472) = 29,189.472; OpEx(stressed) = 223,925.76 - 30,725.76 + 29,189.472 = 222,389.472; NOI(before reserves) = 729,736.8 - 222,389.472 = 507,347.328"
    },
    {
      "id": "stress_maximum_loan",
      "value": 4535993,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Combined downside: EGI -5%; sizing rate +100 bps; cap rate unchanged)",
        "Lender-Terms.pdf | p.1 (Sizing, DSCR, DY, LTV rules; amort 25-yr monthly)"
      ],
      "calculation": "Stressed NOI(before) 507,347.328; Value = 507,347.328/0.065 = 7,805,343.51; LTV limit = 0.65 x 7,805,343.51 = 5,073,473.28. Reserves held constant $4,600; Stressed NCF = 507,347.328 - 4,600 = 502,747.328; Allowable DS = 502,747.328/1.25 = 402,197.8624. Sizing rate = 7.50% => annual constant ≈ 0.0886679. DSCR-limited loan = 402,197.8624 / 0.0886679 ≈ 4,535,993. Debt yield limit = 507,347.328/0.09 = 5,637,192.53. Minimum is DSCR ≈ 4,535,993."
    },
    {
      "id": "subject_lease_monthly_rent",
      "value": 7500,
      "evidence": [
        "Lease-File.pdf | p.2 (Executed first amendment effective 2026-08-01: base rent $7,500/month)",
        "Lease-File.pdf | p.1 (Premises 101)"
      ],
      "calculation": "Stated in executed amendment"
    },
    {
      "id": "subject_lease_expiry",
      "value": "2031-08-31",
      "evidence": [
        "Lease-File.pdf | p.1 (Initial term expires 2031-08-31; renewal not exercised)",
        "Lease-File.pdf | p.2 (Amendment leaves expiration unchanged)"
      ],
      "calculation": "Stated expiry; no extension exercised"
    },
    {
      "id": "subject_lease_deposit",
      "value": 15000,
      "evidence": [
        "Lease-File.pdf | p.1 (Security deposit is $15,000)"
      ],
      "calculation": "Stated"
    },
    {
      "id": "verified_renewal_insurance",
      "value": 27600,
      "evidence": [
        "Property-and-Plan.pdf | p.2 (Insurance renewal confirmation dated 2026-08-25: annual premium $27,600)"
      ],
      "calculation": "Stated underwriting evidence"
    },
    {
      "id": "renewal_option_exercised",
      "value": false,
      "evidence": [
        "Lease-File.pdf | p.1 (Option exists; packet includes no exercise notice or amendment exercising it)"
      ],
      "calculation": "Per instruction, do not extend without evidence; none supplied"
    },
    {
      "id": "prepayment_friction",
      "value": "1% of outstanding principal if prepaid in years 1–2; no stated bank penalty thereafter. No swap assumed.",
      "evidence": [
        "Lender-Terms.pdf | p.1 (Prepayment: 1% in years 1-2; no swap in this scenario)"
      ],
      "calculation": "Stated term"
    }
  ],
  "qualifications": [
    "All analyses and figures rely solely on the supplied packet; no external data, geocoding, comps, or outreach were used.",
    "Rounding: Lender instructs unrounded intermediate values; displayed currency may be rounded for readability. Small variances may appear due to rounding of constants.",
    "Rent roll for unit 101 showed $7,000/month but was superseded by the fully executed amendment to $7,500/month effective 2026-08-01; broker draft is explicitly nonbinding.",
    "Historical (T12) and point-in-time rent roll amounts are not forced to reconcile, per the plan; T12 covers Sep 2025–Aug 2026 cash accounting.",
    "Valuation is indicative only per term sheet (UW NOI before reserves at 6.50% cap); no appraisal is implied.",
    "Management fee underwritten as the greater of T12 actual and 4% of underwritten EGI, per plan.",
    "Replacement reserves underwritten at $0.20/RSF/year; used total RSF from rent roll.",
    "Sensitivity per instruction: EGI -5% with management recalculated; all other OpEx and reserves held constant. Combined downside also increases sizing rate by +100 bps while keeping cap rate unchanged."
  ],
  "summary": "As of 2026-08-31, Market Row totals 23,000 RSF across 8 suites with 7 occupied (87.5% by count; 87.83% by area). The printed rent roll shows $48,600/month base rent, but an executed amendment raises Suite 101 to $7,500/month effective 2026-08-01, bringing effective contractual monthly base to $49,100. T12 results (Sep 2025–Aug 2026) show EGI $723,600, operating expenses $216,000, NOI before reserves $507,600, reserves $9,200, and NCF $498,400. Underwriting per the provided plan yields EGI $768,144, operating expenses $223,925.76 (management at the 4% floor on EGI), NOI before reserves $544,218.24, reserves $4,600, and NCF $539,618.24. Indicative value per lender convention (NOI before reserves at a 6.50% cap) is $8.37MM. Loan sizing at the 6.50% sizing rate and 25-year amortization produces limits: LTV $5.44MM, DSCR $5.33MM, and Debt Yield $6.05MM. The binding maximum is the DSCR at approximately $5.33MM, with sizing annual DS of ~$431.7k (1.25x DSCR), first-year contractual DS at 6.25% of ~$422.2k, and estimated cash-out to the borrower of ~$1.83MM after a 1% origination fee and $48k fixed closing costs. In the combined downside (EGI -5% with management recalculated and sizing rate +100 bps to 7.50%, cap rate unchanged), the DSCR limit binds at approximately $4.54MM; stressed NOI before reserves is ~$507.35k. Insurance renewal is verified at $27,600 annually. The lease renewal option for Suite 101 has not been exercised. Prepayment friction is 1% in years 1–2; no swap is assumed.",
  "blocked": [
    "A downloadable, editable XLSX underwriting workbook (live formulas, sensitivities, and input map) cannot be created or delivered in this direct-text control.",
    "A concise, polished financing memorandum as a PDF or native memo with PDF export cannot be created or delivered in this direct-text control."
  ]
}
